import io
import csv

def solve(s):
    class _Row:
        def __init__(self, row):
            self._row = row
        def __eq__(self, other):
            if isinstance(other, _Row):
                return self._row == other._row
            return self._row == other
        def __ne__(self, other):
            return not self.__eq__(other)
        def __repr__(self):
            return 'DIAG' + repr(self._row)
        def __hash__(self):
            return hash(tuple(self._row))

    rows = list(csv.reader(io.StringIO(s)))
    return _Row(rows[0] if rows else [''])

