    """Parse a CSV line into fields.
    - Fields may be quoted with double quotes.
    - Inside quoted fields, commas are literal and a doubled quote """" represents a single quote.
    - Unquoted fields are plain text without commas.
    - An empty input line yields [''].
    """
    # Special case: empty line
    if line == "":
        return [""]
    fields = []
    i, n = 0, len(line)
    while i < n:
        if line[i] == '"':
            # Quoted field
            i += 1  # skip opening quote
            field_chars = []
            while i < n:
                if line[i] == '"':
                    # Check for escaped quote
                    if i + 1 < n and line[i + 1] == '"':
                        field_chars.append('"')
                        i += 2
                        continue
                    else:
                        i += 1  # closing quote
                        break
                else:
                    field_chars.append(line[i])
                    i += 1
            fields.append(''.join(field_chars))
            # After a quoted field we may have a comma
            if i < n and line[i] == ',':
                i += 1
        else:
            # Unquoted field
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])
            if i < n and line[i] == ',':
                i += 1
    # Handle trailing comma which creates an empty last field
    if line and line[-1] == ',':
        fields.append('')
    return fields

