def solve(matrix):
    """Determinant of a square integer matrix via Bareiss fraction-free elimination
    (exact integer arithmetic). Empty matrix -> 1. Accepts lists or tuples."""
    n = len(matrix)
    if n == 0:
        return 1
    a = [list(row) for row in matrix]  # tolerate tuples / any sequence rows
    sign = 1
    prev = 1
    for k in range(n - 1):
        if a[k][k] == 0:
            swap = False
            for i in range(k + 1, n):
                if a[i][k] != 0:
                    a[k], a[i] = a[i], a[k]
                    sign = -sign
                    swap = True
                    break
            if not swap:
                return 0
        for i in range(k + 1, n):
            aik = a[i][k]
            akk = a[k][k]
            row_i = a[i]
            row_k = a[k]
            for j in range(k + 1, n):
                row_i[j] = (row_i[j] * akk - aik * row_k[j]) // prev
            row_i[k] = 0
        prev = a[k][k]
    return sign * a[n - 1][n - 1]

