def solve(nums):
    """Return the length of the longest strictly increasing subsequence in nums.
    Uses patience sorting with binary search for O(n log n).
    """
    import bisect
    if not nums:
        return 0
    tail = []  # tail[i] = smallest possible tail of an increasing subsequence of length i+1
    for x in nums:
        # find position to replace in tail
        idx = bisect.bisect_left(tail, x)
        if idx == len(tail):
            tail.append(x)
        else:
            tail[idx] = x
    return len(tail)

