def solve(path: str) -> str:
    # Split by '/' and process stack
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # if stack empty, stay at root
        else:
            stack.append(part)
    result = '/' + '/'.join(stack)
    return result

