def solve(n, b):
    """Convert integer n to its representation in base b (2..36) using digits
    0-9 then lowercase a-z, with a leading minus sign for negative n."""
    if n == 0:
        return '0'
    neg = n < 0
    n = abs(n)
    digits = '0123456789abcdefghijklmnopqrstuvwxyz'
    out = []
    while n:
        out.append(digits[n % b])
        n //= b
    return ('-' if neg else '') + ''.join(reversed(out))

