def solve(grid):
    """Count the number of islands (connected components of 1s) in a 2D grid.
    Connections are 4-directional (up, down, left, right).
    Empty grid returns 0.
    """
    if not grid:
        return 0
    n = len(grid)
    m = len(grid[0]) if n else 0
    visited = [[False] * m for _ in range(n)]
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
